index 0000000..7e05992
--- /dev/null
+++ b/e2e/shell.spec.ts
@@ -0,0 +1,216 @@
+/**
+ * app-shell spec: navigation state treatment, persistent runtime status, skip
+ * navigation, and Flat 2.0 surfaces (fill-separated regions, no borders or
+ * shadows, nothing below 12px).
+ */
+import type { Page } from "@playwright/test";
+import { FIXTURE_THREAD_ID } from "./support/routes";
+import { expect, test } from "./support/test";
+
+const DESTINATIONS = [
+  { path: "/threads", active: "Threads" },
+  { path: "/agents", active: "Agents" },
+  { path: "/settings/providers", active: "Settings" },
+] as const;
+const LABELS = ["Threads", "Agents", "Settings"];
+
+for (const { path, active } of DESTINATIONS) {
+  test(`top bar marks ${active} as the active destination on ${path}`, async ({ page }) => {
+    await page.setViewportSize({ width: 1440, height: 900 });
+    await page.goto(path);
+    const nav = page.getByRole("navigation", { name: "Main" });
+    for (const label of LABELS) {
+      const link = nav.getByRole("link", { name: label, exact: true });
+      if (label === active) {
+        await expect(link).toHaveAttribute("aria-current", "page");
+        await expect(link).toHaveClass(/\bbg-ember-soft\b/);
+      } else {
+        await expect(link).not.toHaveAttribute("aria-current");
+      }
+    }
+  });
+}
+
+test("bottom navigation marks the active destination on phones", async ({ page }) => {
+  await page.setViewportSize({ width: 320, height: 800 });
+  await page.goto("/agents");
+  const nav = page.getByRole("navigation", { name: "Main" });
+  await expect(nav.getByRole("link", { name: "Agents" })).toHaveAttribute("aria-current", "page");
+  await expect(nav.getByRole("link", { name: "Threads" })).not.toHaveAttribute("aria-current");
+});
+
+test("runtime status is visible in the top bar on every desktop route", async ({ page }) => {
+  await page.setViewportSize({ width: 1440, height: 900 });
+  for (const path of ["/agents", "/settings/providers"]) {
+    await page.goto(path);
+    const status = page.getByRole("banner").getByRole("status");
+    await expect(status).toHaveText("Connected");
+    await expect(status).toHaveAccessibleName(/runtime connected/i);
+  }
+});
+
+test("first Tab reaches a skip link that moves focus to the main content", async ({ page }) => {
+  await page.setViewportSize({ width: 1440, height: 900 });
+  await page.goto("/agents");
+  await expect(page.getByText("Research Analyst").first()).toBeVisible();
+  await page.keyboard.press("Tab");
+  const skip = page.getByRole("link", { name: "Skip to content" });
+  await expect(skip).toBeFocused();
+  await expect(skip).toBeVisible();
+  await page.keyboard.press("Enter");
+  await expect(page.locator("main#main")).toBeFocused();
+});
+
+test("icon-only controls in the top bar are named", async ({ page }) => {
+  await page.setViewportSize({ width: 1440, height: 900 });
+  await page.goto("/threads");
+  await expect(page.getByRole("banner").getByRole("button", { name: /switch to (light|dark) theme/i })).toBeVisible();
+});
+
+test("shell regions separate by fill with no borders, shadows or sub-12px text", async ({ page }) => {
+  await page.setViewportSize({ width: 1440, height: 900 });
+  await page.goto("/threads");
+  await expect(page.getByRole("complementary", { name: "Threads" })).toBeVisible();
+  const report = await page.evaluate(() => {
+    const token = (name: string) => {
+      const probe = document.createElement("div");
+      probe.style.backgroundColor = `var(${name})`;
+      document.body.append(probe);
+      const value = getComputedStyle(probe).backgroundColor;
+      probe.remove();
+      return value;
+    };
+    const bg = (el: Element | null) => (el ? getComputedStyle(el).backgroundColor : "missing");
+    const shell = [
+      document.querySelector("header"),
+      document.querySelector("aside[aria-label='Threads']"),
+      document.querySelector("nav[aria-label='Main']"),
+    ].filter((el): el is Element => el !== null);
+    const offenders: string[] = [];
+    for (const root of shell) {
+      for (const el of [root, ...Array.from(root.querySelectorAll("*"))]) {
+        const s = getComputedStyle(el);
+        const bordered = ["Top", "Right", "Bottom", "Left"].some(
+          (side) =>
+            parseFloat(s.getPropertyValue(`border-${side.toLowerCase()}-width`)) > 0 &&
+            s.getPropertyValue(`border-${side.toLowerCase()}-color`) !== "rgba(0, 0, 0, 0)",
+        );
+        if (bordered) offenders.push(`border: ${el.tagName}.${el.className}`);
+        if (s.boxShadow !== "none" && !el.matches(":focus-visible")) offenders.push(`shadow: ${el.tagName}`);
+        if (s.backdropFilter !== "none" && s.backdropFilter !== "") offenders.push(`blur: ${el.tagName}`);
+        const hasText = Array.from(el.childNodes).some((n) => n.nodeType === Node.TEXT_NODE && n.textContent?.trim());
+        if (hasText && parseFloat(s.fontSize) < 12) offenders.push(`${s.fontSize}: ${el.textContent?.trim()}`);
+      }
+    }
+    return {
+      offenders,
+      header: bg(document.querySelector("header")),
+      sidebar: bg(document.querySelector("aside[aria-label='Threads']")),
+      main: bg(document.querySelector("main")),
+      chrome: token("--km-chrome"),
+      canvas: token("--km-canvas"),
+    };
+  });
+  expect(report.offenders).toEqual([]);
+  expect(report.header).toBe(report.chrome);
+  expect(report.sidebar).toBe(report.chrome);
+  expect(report.main).toBe(report.canvas);
+});
+
+/** Open the fixture thread and send one message so it is persisted and listed. */
+async function openPersistedThread(page: Page): Promise<void> {
+  await page.goto(`/threads/${FIXTURE_THREAD_ID}`);
+  const composer = page.getByPlaceholder(/Ask your agent anything/i).filter({ visible: true });
+  await composer.fill("Plan my week around the rebrand launch.");
+  await composer.press("Enter");
+}
+
+test("the open thread is marked active in the sidebar without a border", async ({ page }) => {
+  await page.setViewportSize({ width: 1440, height: 900 });
+  await openPersistedThread(page);
+  const active = page.getByRole("complementary", { name: "Threads" }).locator("[aria-current='page']");
+  await expect(active).toHaveCount(1);
+  await expect(active).toHaveClass(/\bbg-ember-soft\b/);
+  // No visible left rule: either no width or a transparent colour.
+  const leftRule = await active.evaluate((el) => {
+    const s = getComputedStyle(el);
+    return { width: parseFloat(s.borderLeftWidth), color: s.borderLeftColor };
+  });
+  expect(leftRule.width === 0 || leftRule.color === "rgba(0, 0, 0, 0)").toBe(true);
+});
+
+for (const width of [768, 1024]) {
+  test(`conversation keeps at least 480px at ${width}px; context opens as a sheet`, async ({ page }) => {
+    await page.setViewportSize({ width, height: 900 });
+    await page.goto(`/threads/${FIXTURE_THREAD_ID}`);
+    const main = page.locator("main#main");
+    await expect(main).toBeVisible();
+    expect((await main.boundingBox())?.width ?? 0).toBeGreaterThanOrEqual(480);
+    await expect(page.getByRole("complementary", { name: "Context" })).toHaveCount(0);
+
+    await page.getByRole("button", { name: "Toggle context panel" }).click();
+    const sheet = page.getByRole("dialog", { name: "Context" });
+    await expect(sheet).toBeVisible();
+    await page.keyboard.press("Escape");
+    await expect(sheet).toHaveCount(0);
+  });
+}
+
+test("context panel is inline at 1440px", async ({ page }) => {
+  await page.setViewportSize({ width: 1440, height: 900 });
+  await page.goto(`/threads/${FIXTURE_THREAD_ID}`);
+  const panel = page.getByRole("complementary", { name: "Context" });
+  await expect(panel).toBeVisible();
+  const { panelBg, surface } = await panel.evaluate((el) => {
+    const probe = document.createElement("div");
+    probe.style.backgroundColor = "var(--km-surface)";
+    document.body.append(probe);
+    const surface = getComputedStyle(probe).backgroundColor;
+    probe.remove();
+    return { panelBg: getComputedStyle(el).backgroundColor, surface };
+  });
+  expect(panelBg).toBe(surface);
+});
+
+test("phone thread drawer is a dismissible sheet", async ({ page }) => {
+  await page.setViewportSize({ width: 320, height: 800 });
+  await page.goto("/threads");
+  await page.getByRole("button", { name: "Open threads" }).click();
+  const drawer = page.getByRole("dialog", { name: "Threads" });
+  await expect(drawer).toBeVisible();
+  await expect(drawer.getByRole("button", { name: "New thread", exact: true })).toBeVisible();
+  await drawer.getByRole("button", { name: "Close threads" }).click();
+  await expect(drawer).toHaveCount(0);
+});
+
+test("sheets close when their layout goes away, so they never reopen on their own", async ({ page }) => {
+  await page.setViewportSize({ width: 1024, height: 900 });
+  await page.goto(`/threads/${FIXTURE_THREAD_ID}`);
+  await page.getByRole("button", { name: "Toggle context panel" }).click();
+  await expect(page.getByRole("dialog", { name: "Context" })).toBeVisible();
+  await page.setViewportSize({ width: 1440, height: 900 });
+  await expect(page.getByRole("complementary", { name: "Context" })).toBeVisible();
+  await page.setViewportSize({ width: 1024, height: 900 });
+  await expect(page.locator("main#main")).toBeVisible();
+  await expect(page.getByRole("dialog")).toHaveCount(0);
+
+  await page.setViewportSize({ width: 320, height: 800 });
+  await page.getByRole("button", { name: "Open threads" }).click();
+  await expect(page.getByRole("dialog", { name: "Threads" })).toBeVisible();
+  await page.setViewportSize({ width: 1024, height: 900 });
+  await page.setViewportSize({ width: 320, height: 800 });
+  await expect(page.getByRole("button", { name: "Open threads" })).toBeVisible();
+  await expect(page.getByRole("dialog")).toHaveCount(0);
+});
+
+test("the context sheet closes when the route changes", async ({ page }) => {
+  await page.setViewportSize({ width: 1024, height: 900 });
+  await page.goto("/agents");
+  await page.goto(`/threads/${FIXTURE_THREAD_ID}`);
+  await page.getByRole("button", { name: "Toggle context panel" }).click();
+  await expect(page.getByRole("dialog", { name: "Context" })).toBeVisible();
+  await page.goBack();
+  await page.goForward();
+  await expect(page.locator("main#main")).toBeVisible();
+  await expect(page.getByRole("dialog")).toHaveCount(0);
+});
diff --git a/openspec/changes/app-shell-flat2/design.md b/openspec/changes/app-shell-flat2/design.md
new file mode 100644
index 0000000..3cf4e6f
--- /dev/null
+++ b/openspec/changes/app-shell-flat2/design.md
@@ -0,0 +1,21 @@
+## Context
+
+See proposal.md. The binding source is `know-me-system/docs/knowme-ui-ux-standard.md`: §3 (Flat 2.0 rules, surface ladder), §4.2 (type floor 12px), §4.4 (pills only for status/metadata), §5 (shell per width), §11 (landmarks, names, status not colour-only). Tokens come from `src/styles/tokens.css` (knowme-brand-tokens).
+
+**Goals:** a shell that passes the Flat 2.0 grep and axe at every harness width, with a readable conversation at 768/1024px. **Non-goals:** page content restyle (agents, settings, chat), a Tauri custom titlebar (desktop change, out of phase), a collapsible icon rail.
+
+## Decisions
+
+1. **Surface mapping.** Top bar, sidebar, bottom nav and thread drawer: `bg-chrome`. Work area: `bg-canvas`. Context panel and menus: `bg-surface` / `bg-raised`. Search and the agent picker trigger: `bg-muted-surface` (filled input, §3.2). Light theme chrome `#FFFFFF` against canvas `#F7F7F8` is the standard's own value, so it isn't adjusted.
+2. **Active state = `bg-ember-soft` + `text-fg` + ember-text icon.** Hover = `bg-hover`. Focus = `focus-visible:bg-hover` plus the existing global ember focus ring. The ring is a functional focus indicator, not decoration (§3.3 bans decorative outlines only), and it keeps focus from depending on fill alone.
+3. **Status label + icon + tone.** `UarStatus` gets `Connected`/`Checking`/`Offline` text, the `Wifi`/`WifiOff`/`Loader` icon and the success/warning/danger text tokens. A compact form (icon + label) goes in the top bar on desktop. The sidebar footer keeps the full form with the hostname.
+4. **Breakpoints.** Phone < 768 (existing `useIsMobile`): bottom nav, thread-list sheet. 768–1279: sidebar inline (260px), context panel as a right sheet. ≥ 1280: sidebar and context panel inline. A small `useMediaQuery` hook avoids a second copy of the matchMedia logic. At 1024 the conversation gets 764px, at 768 it gets 508px.
+5. **Sheet primitive.** Added by hand as `src/components/ui/sheet.tsx` on `@base-ui/react/dialog`, matching the shadcn base-nova API (`Sheet`, `SheetTrigger`, `SheetContent side`, `SheetHeader`, `SheetTitle`, `SheetClose`). The shadcn CLI isn't used, because earlier runs rewrote imports to a stray `cn` package. The scrim is a new `--km-scrim` token (dark `rgb(0 0 0 / 0.6)`, light `rgb(11 15 20 / 0.45)`), because §3.2 says modal priority comes from dimming, not shadow. Panel open state stays in `ui-store`: `rightPanelOpen` drives the inline panel, and a new transient `contextSheetOpen` drives the sheet, so a desktop preference never pops a sheet open at tablet widths.
+6. **Primitive flattening, limited to what the shell uses.** `dialog` overlay → scrim token, no blur; popup `ring-1` removed. `select` trigger → filled muted surface, no border or ring-halo (focus uses the global ring); popup → `bg-raised`, no shadow or ring; separator → spacing. Everything else stays with brand-fidelity-audit.
+7. **`grid-overlay` removed.** At 4% it still reads as a line grid, which §3.3 forbids. The utility and its two usages are deleted.
+8. **Guard test.** `src/test/flat-shell.test.ts` scans `components/layout`, `components/common` and the three primitives for `border`/`divide-`/`shadow`/`backdrop-blur`/`ring-1`/`text-[<12px]` and raw palette classes (`zinc|gray|green|amber|red|…-NNN`), allowing only `border-0`/`border-transparent`. This turns the plan's acceptance grep into a durable test.
+
+## Risks / Trade-offs
+
+- A hand-written sheet can drift from shadcn upstream. It's a thin wrapper, and the upstream base-nova sheet is also a Dialog wrapper, so it's easy to replace later.
+- The runtime status in the top bar adds one more health poll consumer. `useHealth` is already shared through the entity graph/hook cache, so no extra requests are made.
diff --git a/openspec/changes/app-shell-flat2/proposal.md b/openspec/changes/app-shell-flat2/proposal.md
new file mode 100644
index 0000000..b198b7a
--- /dev/null
+++ b/openspec/changes/app-shell-flat2/proposal.md
@@ -0,0 +1,20 @@
+## Why
+
+The application shell (top bar, threads sidebar, context panel, mobile navigation and drawer) still uses the pre-rebrand treatment: 1px borders between regions, drop shadows, backdrop blur, a faint grid texture on the work area, raw palette status dots (`bg-green-400`, `bg-amber-400`), 9–11px text and an outlined primary button. The binding KnowMe UI/UX standard (§3 Flat 2.0, §4, §5, §11) forbids all of these. The harness also found that at 768px the sidebar and context panel both stay open and squeeze the conversation to ~150px.
+
+## What Changes
+
+- Surface ladder: canvas work area; chrome top bar, sidebar and bottom nav; surface context panel and menus; regions separate by fill only. No borders, dividers, shadows, blur or grid texture.
+- Navigation states: the active destination gets an ember-tinted fill plus stronger text and icon; hover uses the hover token; keyboard focus gets a fill plus the focus ring. This applies to top-bar links, bottom-nav items and the active thread.
+- Status: the runtime status uses status tokens with an icon and a text label (not colour alone), and is visible in the top bar on every desktop route (§5.1 persistent status). `StatusBadge` becomes a 12px status pill.
+- Type: nothing below 12px in the shell.
+- Controls: "New thread" is the primary (ember) button. Search is a filled field. The agent picker for new threads is the Base UI `Select` instead of a hand-rolled dropdown.
+- Overlays: the mobile drawer and the context panel below 1280px become a `Sheet` (Base UI Dialog) with a scrim, focus trap and Escape to close. The inline context panel shows only at ≥1280px, which fixes the 768px collapse.
+- Accessibility: a skip link to the main content, and names on every icon-only control.
+- Primitives used by the shell (`dialog`, `select`, new `sheet`) lose their ring outlines, shadows and backdrop blur, and gain a `--km-scrim` token.
+
+## Impact
+
+- Code: `src/components/layout/*`, `src/components/common/*`, `src/components/ui/{dialog,select,sheet}.tsx`, `src/styles/tokens.css`, `src/index.css`.
+- No data or API changes. Panel state stays per-session in `ui-store`.
+- Pages inside the shell (agents, settings, threads content) are restyled by later changes.
